%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% This script plots all results presented in Racz et al. "Reduced temporal 
% variability of cortical excitation/inhibition ratio in schizophrenia"
% (2025). The script loads the analysis outcomes from ws_results.mat, which
% can be (re-)generated by running script_o2_statistics_IRASA_bimodal.m.
% The following figures are generated:
% - Illustration of the global power spectra (mixd, frac and osci) in HC
%   and SZ (not included in Racz et al. (2025)).
%
% Note that EEGLAB (or subfolder 'eeglab_functions') needs to be added to
% the path for generating topoplots.
%
% Note that Figure 2 in Racz et al. (2025) were generated manually for
% illustrative purposes using the BrainNet Viewer software (Xia, et al.
% "BrainNet Viewer: a network visualization tool for human brain
% connectomics." PloS one (2013)).
% 
% Author: F. Samuel Racz, The University of Texas at Austin
% email: fsr324@austin.utexas.edu
% last modified: 02/07/2025
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

%% adding dependencies and loading outcomes
addpath(genpath('eeglab_functions'))
addpath(genpath('functions'))
addpath('miscellaneous')

load('ws_results.mat')
load('ws_correlations.mat')
load('ws_55ch_montage.mat')

chlab = M.lab;
Mr = func_map_to_RSN(M);
vn = Mr.lab{1};
sm = Mr.lab{2};
da = Mr.lab{3};
val = Mr.lab{4};
fp = Mr.lab{5};
dmn = Mr.lab{6};

%% plot global spectra - illustration (not included in Racz et al. (2025))
[f01, f02, spec_hc, spec_sz, struct_stat_spec] = func_plot_GA_spectra(struct_hc,struct_sz,0,1,1);
exportgraphics(f01,'figures/fig_GA_spectra.png','resolution',400)
close(f01)
exportgraphics(f02,'figures/fig_GA_matrices.png','resolution',400)
close(f02)

%% plot spectral bimodality illustration (Figure 1)
[f1, ~, ~] = func_plot_spectral_bimodality(struct_hc,struct_sz,'F5','P3',1);
exportgraphics(f1,'figures/fig_1_bimodal_spectra_illustration.png','resolution',400)
close(f1)

%% Illustration of electrode montage (Figure 2)
% The electrode montage was created manually with BrainNet Viewer. Channel
% allocations for different resting-state networks are found in the
% variable 'Mr'.
%
% Reference: Xia, et al. "BrainNet Viewer: a network visualization tool for
% human brain connectomics." PloS one (2013)

%% plot bimodal spectra (Figure 3)
[f3] = func_plot_slope_diff(p_bdiff_mean_hc,p_bdiff_mean_sz,chanlocs);
exportgraphics(f3,'figures/fig_3_slope_diff.png','resolution',400)
close(f3)

%% plot difference in spectral slope variances in high-frequency regime (Figure 4)
[f4] = func_plot_slope_variances(struct_stat_beta, table_sign_beta, struct_stat_rsn_beta, chanlocs, 'var', 'hi', 0);
exportgraphics(f4,'figures/fig_4_slope_variance_RSN.png','resolution',400)
close(f4)

%% plot spectral slope variances in low-frequency regime (Supplementary Figure S1)
[fs1] = func_plot_slope_variances(struct_stat_beta, table_sign_beta, struct_stat_rsn_beta, chanlocs, 'var', 'lo', 0);
exportgraphics(fs1,'figures/fig_s1_slope_variance_RSN.png','resolution',400)
close(fs1)

%% plot spectral slope correlation - RSN-wise (Figure 5)
f5 = figure('color','w','units','normalized','outerposition',[0.25,0.1,0.5,0.7]);
sc = scatter(corr_panss_rsn_beta_pos.res_eeg{1},corr_panss_rsn_beta_pos.res_panss{1},140,'LineWidth',1.5,'MarkerEdgeColor',[0.4 0.4 0.4],'MarkerFaceColor',[0.7 0.9 1]);
ls = lsline;
ls.LineWidth = 3;
ls.Color = [0.8 0 0];
set(gca,'LineWidth',1,'FontSize',24,'box','on')
xlabel('Dorsal attention network \sigma(\beta_{\it{hi}})', 'FontSize', 28, 'visible', 'on')
ylabel('PANSS - Positive','FontSize',28,'visible','on')
title('Relationship between \sigma(\beta_{\it{hi}}) and clinical symptoms','FontSize',28)
exportgraphics(f5,'figures/fig_5_corr_panss_rsn_pos.png','resolution',400)
close(f5)


